;gap:16px;margin:3px 0 23px}.section-head h2{font-size:21px;margin:0;font-weight:500}.section-head p{color:var(--muted);font-size:12px;margin:5px 0 0}.subtle-button{background:var(--raised);border-radius:10px;padding:5px 13px;font-size:11px}.memory-editor{border:1px solid var(--line);border-radius:17px;background:var(--panel);padding:18px}.memory-editor textarea{min-height:80px;font-size:13px}.memory-meta{display:flex;justify-content:space-between;align-items:center;gap:12px;color:var(--muted);font-size:10px}.memory-list{display:flex;flex-direction:column;gap:12px;margin-top:24px}.memory-card{padding:18px;border:1px solid var(--line);border-radius:16px;background:var(--panel)}.memory-card p{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}.memory-card .row{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:12px}.memory-card button{font-size:11px;color:var(--muted);min-height:32px;padding:3px 8px}.memory-card button:last-child{color:var(--danger)}.note{color:var(--muted);font-size:11px;margin:17px 0;line-height:2}.knowledge-note{padding:14px 17px;background:#4c9ab808;border:1px solid var(--line);border-radius:13px;margin-top:0}.empty{text-align:center;color:var(--muted);padding:28px 10px;font-size:12px}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.metric{border:1px solid var(--line);border-radius:16px;padding:18px;background:var(--panel);min-width:0;overflow-wrap:anywhere}.metric strong{display:block;font:30px Arial,sans-serif;margin-top:15px}.metric span{font-size:11px;color:var(--muted)}.services{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px;margin:23px 0 0}.service{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:15px;display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:12px}.badge{font-size:10px;color:var(--muted)}.badge.good{color:var(--accent)}.badge.warn{color:var(--danger)}dialog{background:var(--pa