<dialog id="confirmDialog" style="background:var(--panel);color:var(--ink);border:1px solid var(--line);border-radius:18px;padding:24px;max-width:calc(100% - 32px);width:360px"><p id="confirmText"></p><div style="display:flex;gap:12px;margin-top:20px"><button id="confirmYes" class="send" data-i18n="confirm"></button><button id="confirmNo" class="subtle-button" data-i18n="cancel"></button></div></dialog>
<script>
(()=>{
'use strict';
const L=@json($labels),lang=@json($locale),$=id=>document.getElementById(id),app=window.Bale&&window.Bale.WebApp;
let session=null,authorized=false,busy=false,currentView='chat',state={messages:[],memories:[]},editing=null,overviewLoaded=false,pollTimer=null,syncing=false;
const UI=({
fa:{menu:'همراه نوا',menu_hint:'با گفت‌وگو کارها را پیش ببر؛ یادداشت‌ها و جزئیات را از اینجا ببین.',close_menu:'بستن منو',back_chat:'بازگشت به گفتگو',assistant_subtitle:'دستیار هوشمند تو',welcome:'قدم بعدی را با هم برداریم',intro:'سؤالت را بپرس یا کاری را به من بسپار. از وضعیت سرویس‌ها تا پروژه‌ها و رشد کسب‌وکارت.',memory:'یادداشت‌ها و ترجیحات',memory_hint:'چیزهایی که می‌خواهی دربارهٔ روش کارمان به خاطر بسپارم.',memory_count:'یادداشت شخصی',knowledge_note:'این یادداشت‌ها همهٔ دانش نوا نیستند. دانش پروژه‌ها، مستندات و ابزارهای متصل جدا هستند؛ دربارهٔ هرکدام در گفتگو بپرس.',status:'جزئیات اتصال و پایش',operations:'پیگیری کارها',projects_label:'پروژه‌ها و قدم بعدی',projects_prompt:'پروژه‌های ما و کارهای باز را با منابع و تاریخشان مرور کن؛ قدم بعدی و اطلاعاتی که نیاز به بررسی تازه دارند را بگو.',servers_label:'وضعیت سرویس‌ها',network_label:'بررسی رله و اتصال‌ها',network_prompt:'وضعیت فعلی رله و اتصال‌های مهم را با ابزارهای موجود بررسی کن. زمان بررسی، قطعی یا اطلاعات نامعلوم را روشن بگو.',develop_label:'کارهای توسعه',hint:'پاسخ و نتیجهٔ کار را همین‌جا دنبال کن.',language_label:'زبان رابط',theme:'روشن / تیره',online:'آمادهٔ گفتگو',thinking:'در حال بررسی درخواستت…'},
en:{menu:'Your Nava',menu_hint:'Talk to get things done. Find your notes and details here.',close_menu:'Close menu',back_chat:'Back to chat',assistant_subtitle:'Your intelligent assistant',welcome:'Let’s take the next step',intro:'Ask a question or give me a task. From your services to projects and business growth.',memory:'Notes & preferences',memory_hint:'Things you want me to remember about how we work.',memory_count:'personal notes',knowledge_note:'These notes are not all of Nava’s knowledge. Project knowledge, documents and connected tools are separate; ask about them in chat.',status:'Connections & monitoring',operations:'Work follow-up',projects_label:'Projects & next steps',projects_prompt:'Review our projects and open work with sources and dates. Explain the next step and which facts need a fresh check.',servers_label:'Service status',network_label:'Relay & connections',network_prompt:'Check the current relay and key connections with the available tools. State the observation time, outages and unknown information.',develop_label:'Development work',hint:'Follow the answer and task result right here.',language_label:'Interface language',theme:'Light / dark',online:'Ready to chat',thinking:'Looking into your request…'},
tr:{menu:'Senin Nava’n',menu_hint:'İşleri konuşarak ilerlet. Notların ve ayrıntılar burada.',close_menu:'Menüyü kapat',back_chat:'Sohbete dön',assistant_subtitle:'Akıllı asistanın',welcome:'Bir sonraki adımı birlikte atalım',intro:'Bir soru sor veya bana bir görev ver. Hizmetlerinden projelerine ve işinin büyümesine kadar.',memory:'Notlar ve tercihler',memory_hint:'Birlikte çalışma biçimimiz hakkında hatırlamamı istediklerin.',memory_count:'kişisel not',knowledge_note:'Bu notlar Nava’nın tüm bilgisi değildir. Proje bilgileri, belgeler ve bağlı araçlar ayrıdır; sohbette bunları sorabilirsin.',status:'Bağlantılar ve izleme',operations:'İş takibi',projects_label:'Projeler ve sonraki adım',projects_prompt:'Projelerimizi ve açık işleri kaynak ve tarihleriyle incele. Sonraki adımı ve yeniden kontrol edilmesi gereken bilgileri belirt.',servers_label:'Hizmet durumu',network_label:'Röle ve bağlantılar',network_prompt:'Mevcut araçlarla rölenin ve önemli bağlantıların güncel durumunu kontrol et. Kontrol zamanını, kesintileri ve bilinmeyen bilgileri açıkça belirt.',develop_label:'Geliştirme işleri',hint:'Yanıtı ve görevin sonucunu buradan takip et.',language_label:'Arayüz dili',theme:'Açık / koyu',online:'Sohbete hazır',thinking:'İsteğini inceliyorum…'}
})[lang]||{};
const brand=lang==='fa'?'نوا':'Nava',rename=value=>String(value??'').replace(/\bHermes\b/g,'Nava').replace(/هرمس/g,'نوا');
const number=n=>new Intl.NumberFormat(lang==='fa'?'fa-IR':lang).format(n),t=k=>k==='brand'||k==='assistant'?brand:rename(UI[k]||L[k]||L.unknown);
document.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=t(e.dataset.i18n));
document.querySelectorAll('[data-label]').forEach(e=>e.setAttribute('aria-label',t(e.dataset.label)));
const menu=$('assistantMenu');
$('openMenu').onclick=()=>{menu.showModal();$('openMenu').setAttribute('aria-expanded','true')};
$('closeMenu').onclick=()=>menu.close();
menu.addEventListener('close',()=>$('openMenu').setAttribute('aria-expanded','false'));
menu.addEventListener('click',e=>{if(e.target===menu){const r=menu.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)menu.close()}});
$('backToChat').onclick=()=>{show('chat');$('message').focus()};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!menu.open&&!$('confirmDialog').open&&currentView!=='chat'){e.preventDefault();show('chat');$('message').focus()}});
function fitViewport(){const h=window.visualViewport?.height;document.documentElement.style.setProperty('--app-height',(h||window.innerHeight)+'px');chatLayoutChanged()}
window.addEventListener('resize',fitViewport);window.visualViewport?.addEventListener('resize',fitViewport);
$('message').placeholder=t('placeholder');$('memoryText').placeholder=t('memory_placeholder');$('theme').setAttribute('aria-label',t('theme'));$('clear').setAttribute('aria-label',t('new_chat'));$('language').value=lang;
$('connection').textContent=t('connecting');$('gateTitle').textContent=t('connecting');$('gateText').textContent=t('private');
const dark=app?.colorScheme==='dark'||window.matchMedia('(prefers-color-scheme: dark)').matches;document.body.classList.toggle('light',!dark);
$('theme').onclick=()=>document.body.classList.toggle('light');$('language').onchange=()=>{const u=new URL(location.href);u.searchParams.set('lang',$('language').value);location.assign(u.toString())};
function notice(code){$('noticeText').textContent=code?t(code):'';$('notice').classList.toggle('hidden',!code)}
function fail(code){notice(code||'unknown')}
function confirmAction(text){return new Promise(resolve=>{const d=$('confirmDialog');$('confirmText').textContent=text;const done=value=>{d.close();resolve(value)};$('confirmYes').onclick=()=>done(true);$('confirmNo').onclick=()=>done(false);d.oncancel=e=>{e.preventDefault();done(false)};d.showModal()})}
function show(view){if(!['chat','memory','status','operations'].includes(view))return;if(menu.open)menu.close();if(view==='operations')loadOperations();currentView=view;$('backToChat').classList.toggle('hidden',view==='chat');document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});['chat','memory','status','operations'].forEach(v=>$('view-'+v).classList.toggle('hidden',v!==view));$('composerArea').classList.toggle('hidden',!authorized||view!=='chat');if(view==='status'){if(!overviewLoaded)overview();monitor()}if(view==='chat'){followChat=true;scroll(true)}}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));
function headers(){const h={'Accept':'application/json'};if(session&&session.expires_at*1000>Date.now())h['X-Hermes-Session']=session.token;else if(app?.initData)h['X-Bale-Init-Data']=app.initData;return h}
async function api(path,body,timeout=30000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const res=await fetch('/bale/hermes/'+path,{method:body===undefined?'GET':'POST',credentials:'omit',headers:{...headers(),...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store',redirect:'error',signal:controller.signal});const type=res.headers.get('content-type')||'';if(!type.includes('application/json'))throw {code:'service_unavailable'};const data=await res.json();if(res.status===401||res.status===403){authorized=false;session=null;try{sessionStorage.removeItem('hermes-miniapp-session')}catch{};$('connection').textContent=t('session_expired');$('send').disabled=true;throw {code:'session_expired'}}if(!res.ok||data.ok===false)throw {code:res.status===429?'rate_limited':data.code||'unknown'};return data}catch(e){throw {code:e.code||'connection_error'}}finally{clearTimeout(timer)}}
function date(at){return new Date(at*1000).toLocaleTimeString(lang==='fa'?'fa-IR':lang,{hour:'2-digit',minute:'2-digit'})}
// Keep the latest message visible after authentication, tab changes and late font/layout changes.
let followChat=true,chatScrollFrame=null;
function scroll(instant=false){if(!authorized||currentView!=='chat')return;cancelAnimationFrame(chatScrollFrame);chatScrollFrame=requestAnimationFrame(()=>{if(!authorized||currentView!=='chat')return;$('main').scrollTo({top:$('main').scrollHeight,behavior:instant?'instant':'smooth'})})}
$('main').addEventListener('scroll',()=>{if(currentView==='chat')followChat=$('main').scrollHeight-$('main').clientHeight-$('main').scrollTop<80},{passive:true});
function chatLayoutChanged(){if(followChat)scroll(true)}
if(typeof ResizeObserver!=='undefined'){const observer=new ResizeObserver(chatLayoutChanged);observer.observe($('messages'));observer.observe($('main'))}
if(document.fonts?.ready)document.fonts.ready.then(chatLayoutChanged);
window.addEventListener('resize',chatLayoutChanged);
window.visualViewport?.addEventListener('resize',chatLayoutChanged);
function render(){const keepLatest=followChat;const list=$('messages');list.replaceChildren();$('welcome').classList.toggle('hidden',state.messages.length>0);for(const m of state.messages){const box=document.createElement('article'),head=document.createElement('div'),text=document.createElement('div');box.className='message '+(m.role==='user'?'user':'assistant');head.className='message-head';head.textContent=(m.role==='user'?t('you'):t('assistant'))+' · '+date(m.at);text.className='message-text';text.dir='auto';text.textContent=m.text;box.append(head,text);if(m.status==='uncertain'||(m.status==='pending'&&Date.now()/1000-m.at>=600)){const s=document.createElement('div');s.className='delivery';s.textContent=t('uncertain');box.append(s)}if(m.role==='assistant'){const row=document.createElement('div'),copy=document.createElement('button');row.className='message-actions';copy.textContent=t('copy');copy.onclick=async()=>{try{await navigator.clipboard.writeText(m.text);copy.textContent=t('copied')}catch{copy.textContent=t('copy')}};row.append(copy);box.append(row)}list.append(box)}$('memoryCount').textContent=number(state.memories.length)+' '+t('memory_count');$('memoryList').replaceChildren();if(!state.memories.length){const e=document.createElement('div');e.className='empty';e.textContent=t('memory_empty');$('memoryList').append(e)}for(const m of state.memories){const card=document.createElement('article'),p=document.createElement('p'),row=document.createElement('div'),time=document.createElement('span'),actions=document.createElement('div'),edit=document.createElement('button'),del=document.createElement('button');card.className='memory-card';p.dir='auto';p.textContent=m.text;row.className='row';time.className='caption';time.textContent=new Date(m.updated_at*1000).toLocaleDateString(lang==='fa'?'fa-IR':lang);if(m.source==='owner_chat')time.textContent+=' · '+t('memory_source_owner');edit.textContent=t('edit');edit.onclick=()=>{editing=m.id;$('memoryText').value=m.text;$('memoryText').focus();$('cancelMemory').classList.remove('hidden');$('memoryText').dispatchEvent(new Event('input'))};del.textContent=t('delete');del.onclick=async()=>{if(!await confirmAction(t('delete_confirm')))return;del.disabled=true;try{const d=await api('memory',{action:'delete',id:m.id});state=d.state;render()}catch(e){fail(e.code)}finally{del.disabled=false}};actions.append(edit,del);row.append(time,actions);card.append(p,row);$('memoryList').append(card)}if(keepLatest)scroll(true)}
function pending(on){busy=on;$('send').disabled=on||!authorized;$('clear').disabled=on;$('typing').classList.toggle('hidden',!on);$('connection').textContent=t(on?'assistant_subtitle':'online');$('message').setAttribute('aria-busy',String(on))}
async function start(){if(!app?.initData){$('gateTitle').textContent=t('open_bale');$('gateText').textContent=t('open_hint');$('connection').textContent=t('private');return}try{notice('');const launch=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(app.initData)))).map(x=>x.toString(16).padStart(2,'0')).join('');try{const saved=JSON.parse(sessionStorage.getItem('hermes-miniapp-session'));if(saved?.launch===launch&&saved.session?.expires_at*1000>Date.now())session=saved.session}catch{}const d=await api('session');if(d.session){session=d.session;try{sessionStorage.setItem('hermes-miniapp-session',JSON.stringify({launch,session}))}catch{}}state=d.state;authorized=true;$('gate').classList.add('hidden');$('main').classList.remove('hidden');$('connection').textContent=t('online');$('send').disabled=false;render();show(currentView);schedulePoll()}catch(e){$('gateTitle').textContent=t('open_bale');$('gateText').textContent=t(e.code);fail(e.code)}}
function schedulePoll(){clearTimeout(pollTimer);const waiting=state.messages.some(m=>['pending','uncertain'].includes(m.status)&&Date.now()/1000-m.at<600);pending(waiting);if(waiting&&authorized)pollTimer=setTimeout(sync,3000)}
async function sync(){if(syncing)return;if(!authorized){await start();return}syncing=true;try{const d=await api('state');state=d.state;render();notice('')}catch(e){fail(e.code)}finally{syncing=false;schedulePoll()}}
$('retry').onclick=sync;
$('chatForm').onsubmit=async e=>{e.preventDefault();if(busy||!authorized)return;const text=$('message').value.trim();if(!text)return;const learn=text.match(/^(?:یاد بگیر|به خاطر بسپار|remember|learn|hatırla)\s*[:：]\s*([\s\S]+)$/iu);if(learn){if(Array.from(learn[1]).length>500){show('memory');$('memoryText').value=learn[1];$('memoryText').dispatchEvent(new Event('input'));$('memoryText').focus();fail('memory_limit');return}pending(true);try{const d=await api('memory',{action:'save',text:learn[1]});state=d.state;$('message').value='';sizeComposer();render();notice('memory_saved')}catch(e){fail(e.code)}finally{pending(false)}return}const id=crypto.randomUUID();pending(true);notice('');$('message').value='';sizeComposer();state.messages.push({id,role:'user',text,at:Date.now()/1000,status:'pending'});followChat=true;render();scroll();try{const d=await api('chat',{id,text},25000);state=d.state;render();if(d.delivery==='uncertain')fail('uncertain')}catch(e){const m=state.messages.find(m=>m.id===id);if(m)m.status='uncertain';render();fail(e.code)}finally{schedulePoll();scroll()}};
function sizeComposer(){const input=$('message');input.style.height='auto';input.style.height=Math.min(input.scrollHeight,148)+'px'}
$('message').addEventListener('input',sizeComposer);
$('message').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('chatForm').requestSubmit()}};
document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{$('message').value=t(b.dataset.prompt);sizeComposer();$('message').focus()});
$('clear').onclick=async()=>{if(!authorized||busy||!await confirmAction(t('clear_confirm')))return;try{const d=await api('history/clear',{});state=d.state;render();notice('')}catch(e){fail(e.code)}};
$('memoryText').oninput=()=>$('memoryLength').textContent=number(Array.from($('memoryText').value).length)+' / 500';
function resetMemory(){editing=null;$('memoryText').value='';$('memoryText').dispatchEvent(new Event('input'));$('cancelMemory').classList.add('hidden')}
$('cancelMemory').onclick=resetMemory;
$('memoryForm').onsubmit=async e=>{e.preventDefault();if(!authorized)return;const text=$('memoryText').value.trim();if(!text)return;$('saveMemory').disabled=true;try{const d=await api('memory',{action:'save',id:editing,text});state=d.state;resetMemory();render();notice('memory_saved')}catch(e){fail(e.code)}finally{$('saveMemory').disabled=false}};
async function overview(){if(!authorized)return;$('refresh').disabled=true;try{const d=await api('overview',undefined,45000);$('running').textContent=d.summary?.qemu?.running==null?'—':number(d.summary.qemu.running);$('stopped').textContent=d.summary?.qemu?.stopped==null?'—':number(d.summary.qemu.stopped);$('containers').textContent=d.summary?.lxc?.running==null?'—':number(d.summary.lxc.running);$('updated').textContent=t('updated')+': '+date(d.utc||Date.now()/1000);$('services').replaceChildren();const names={'proxmox-ir':'Proxmox · IR','proxmox-ir-shell':'Host management','whm-ir':'WHM · IR','whm-de':'WHM · DE','n8n-ir':'n8n','plesk-ir':'Plesk · Windows'};for(const[k,v]of Object.entries(d.integrations||{})){const row=document.createElement('div'),name=document.createElement('span'),badge=document.createElement('span');row.className='service';name.textContent=names[k]||k;name.dir='ltr';badge.className='badge'+(v.connected===true?' good':v.connected===false?' warn':'');badge.textContent=t(v.connected===true?'verified':v.connected===false?(v.configured?'not_verified':'needs_setup'):v.configured?'configured':'needs_setup');row.append(name,badge);$('services').append(row)}overviewLoaded=true;notice(d.overview_available===false?'service_unavailable':'')}catch(e){fail(e.code)}finally{$('refresh').disabled=false}}
// Hermes monitoring panel (read-only).
const monitorText=({fa:{title:'پایش و گزارش خطا',hourly:'بررسی تیکت‌ها هر دقیقه؛ ارسال با تأیید تو',last:'آخرین بررسی',sent:'پاسخ‌های ارسال‌شده',errors:'۵ خطای اخیر',enabled:'فعال',disabled:'غیرفعال',loading:'در حال دریافت وضعیت…',unavailable:'دریافت وضعیت ممکن نشد؛ دوباره تازه‌سازی کنید.',empty:'خطایی ثبت نشده است.',count:'تعداد',request:'شناسه پیگیری'},en:{title:'Monitoring and error log',hourly:'Minute ticket review; owner approval',last:'Last review',sent:'Replies sent',errors:'5 recent errors',enabled:'Enabled',disabled:'Disabled',loading:'Loading status…',unavailable:'Status unavailable. Refresh to retry.',empty:'No errors recorded.',count:'Count',request:'Request ID'},tr:{title:'İzleme ve hata kaydı',hourly:'Dakikalık talep kontrolü; onaylı gönderim',last:'Son kontrol',sent:'Gönderilen yanıtlar',errors:'Son 5 hata',enabled:'Etkin',disabled:'Devre dışı',loading:'Durum yükleniyor…',unavailable:'Durum alınamadı. Yenileyerek tekrar deneyin.',empty:'Kaydedilmiş hata yok.',count:'Sayı',request:'İstek kimliği'}})[lang]||{title:'Monitoring',hourly:'Minute review; owner approval',last:'Last review',sent:'Replies sent',errors:'Recent errors',enabled:'Enabled',disabled:'Disabled',loading:'Loading…',unavailable:'Status unavailable.',empty:'No errors recorded.',count:'Count',request:'Request ID'};
let monitorBusy=false;
for(const[id,key]of Object.entries({monitorTitle:'title',monitorEnabledLabel:'hourly',monitorLastLabel:'last',monitorSentLabel:'sent',monitorErrorsTitle:'errors'}))$(id).textContent=monitorText[key];
function monitorDate(value){const n=typeof value==='number'?value:typeof value==='string'?Date.parse(value)/1000:NaN;const at=new Date(n*1000);return Number.isFinite(n)&&n>0&&!Number.isNaN(at.getTime())?at.toLocaleString(lang==='fa'?'fa-IR':lang):'—'}
function monitorCount(value,fallback=0){return Number.isSafeInteger(value)&&value>=0?value:fallback}
function monitorAutomation(result){if(result.status!=='fulfilled'||result.value?.ok!==true||typeof result.value.automation?.enabled!=='boolean'){$('monitorAutomationState').textContent=monitorText.unavailable;for(const id of ['monitorEnabled','monitorLast','monitorSent'])$(id).textContent='—';return}const a=result.value.automation;$('monitorAutomationState').textContent='';$('monitorEnabled').textContent=monitorText[a.enabled?'enabled':'disabled'];$('monitorLast').textContent=monitorDate(a.last_run_at);$('monitorSent').textContent=number(monitorCount(a.sent_replies))}
function monitorErrors(result){const list=$('monitorErrors');list.replaceChildren();if(result.status!=='fulfilled'||result.value?.ok!==true||!Array.isArray(result.value.errors)){$('monitorErrorsState').textContent=monitorText.unavailable;return}const rows=result.value.errors.slice(0,5);$('monitorErrorsState').textContent=rows.length?'':monitorText.empty;for(const item of rows){const row=item&&typeof item==='object'?item:{},card=document.createElement('article'),line=document.createElement('p'),ref=document.createElement('p');const code=typeof row.code==='string'&&/^[A-Za-z0-9_-]{1,80}$/.test(row.code)?row.code:'unknown';const id=typeof row.request_id==='string'&&/^[A-Za-z0-9_-]{8,80}$/.test(row.request_id)?row.request_id:'—';card.className='memory-card';line.dir='auto';line.textContent=code+' · '+monitorDate(row.utc)+' · '+monitorText.count+': '+number(monitorCount(row.count,1));ref.className='note';ref.dir='auto';ref.textContent=monitorText.request+': '+id;card.append(line,ref);list.append(card)}}
async function monitor(){if(!authorized||monitorBusy)return;monitorBusy=true;$('monitorAutomationState').textContent=monitorText.loading;$('monitorErrorsState').textContent=monitorText.loading;try{const results=await Promise.allSettled([api('automation'),api('errors')]);monitorAutomation(results[0]);monitorErrors(results[1])}finally{monitorBusy=false}}
// End Hermes monitoring panel.
$('refresh').onclick=()=>{overview();monitor()};
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&authorized)sync()});
